"""CBSE Class 11 Biology, chapters 16-19: Excretory Products and their Elimination, Locomotion and Movement,
Neural Control and Coordination, Chemical Coordination and Integration.

Fact tables for g11_chemistry_kit.py; filtration and reabsorption figures are computed here.
"""
from __future__ import annotations

from qbank import F, mcq, num

P = 'cbse-g11-biology'


def _w(good, cands, fmt=str):
    out = []
    for c in cands:
        s = fmt(c)
        if s != fmt(good) and s not in out:
            out.append(s)
    return out[:3]


# ---------------------------------------------------------------- ch16 excretion

def gfr_calc(r):
    gfr = r.choice([110, 115, 120, 125, 130])
    urine = r.choice([1.0, 1.2, 1.5, 1.8, 2.0])
    t = r.choice(['day', 'reabsorbed'])
    per_day = gfr * 60 * 24 / 1000
    if t == 'day':
        good = f'{num(per_day, 1)} L'
        return mcq(f'If the glomerular filtration rate (GFR) of a person is {gfr} mL per minute, what volume of filtrate is formed per day?', good,
                   [f'{num(x, 1)} L' for x in (gfr * 60 / 1000, per_day / 10, gfr * 24 / 1000)],
                   f'{gfr} mL/min × 60 × 24 = {num(gfr * 1440, 0)} mL ≈ {num(per_day, 1)} L per day.', r)
    pct = (per_day - urine) / per_day * 100
    good = f'{num(pct, 1)}%'
    return mcq(f'A person has a GFR of {gfr} mL per minute and passes {num(urine, 1)} L of urine a day. What percentage of the filtrate is reabsorbed?', good,
               [f'{num(x, 1)}%' for x in (100 - pct, pct - 10, urine / per_day * 1000)],
               f'Filtrate = {gfr} × 1440 mL = {num(per_day, 1)} L/day; reabsorbed = ({num(per_day, 1)} − {num(urine, 1)})/{num(per_day, 1)} × 100 = {good}.', r)


def gfr_written(r):
    gfr = r.choice([110, 115, 120, 125, 130])
    urine = r.choice([1.0, 1.2, 1.5, 1.8])
    per_day = gfr * 1440 / 1000
    pct = (per_day - urine) / per_day * 100
    return {'stem': f'The GFR of a healthy person is {gfr} mL per minute and the urine output is {num(urine, 1)} L per day. Calculate (i) the filtrate formed per day and (ii) the percentage of filtrate reabsorbed.',
            'answer': f'(i) {num(per_day, 1)} L per day; (ii) {num(pct, 1)}%',
            'key': f'(i) {gfr} × 60 × 24 = {num(gfr * 1440, 0)} mL ≈ {num(per_day, 1)} L (1); (ii) ({num(per_day, 1)} − {num(urine, 1)})/{num(per_day, 1)} × 100 = {num(pct, 1)}% (1).',
            'distractors': [f'(i) {num(gfr * 60 / 1000, 1)} L per day; (ii) {num(pct, 1)}%', f'(i) {num(per_day, 1)} L per day; (ii) {num(100 - pct, 1)}%', f'(i) {num(per_day / 10, 1)} L per day; (ii) 50%'],
            'marks': 2}


