# ---------------------------------------------------------------- ch17 locomotion

def sarcomere(r):
    L = r.choice([2.2, 2.4, 2.5, 2.6, 2.8, 3.0])
    sh = r.choice([0.2, 0.3, 0.4])
    band, good, why = r.choice([
        ('the A-band', 'It remains the same', 'the A-band is the length of the thick (myosin) filaments, which do not shorten'),
        ('the I-band', 'It decreases', 'thin (actin) filaments slide towards the centre of the A-band, so the I-band shortens'),
        ('the H-zone', 'It decreases or disappears', 'thin filaments move into the centre of the A-band, overlapping the thick filaments'),
        ('each myosin (thick) filament', 'It remains the same', 'filaments slide past each other; they do not change their own length')])
    opts = ['It remains the same', 'It decreases', 'It increases', 'It decreases or disappears']
    wrong = [o for o in opts if o != good][:3]
    return mcq(f'During contraction, a sarcomere shortens from {num(L, 1)} µm to {num(L - sh, 1)} µm. What happens to the length of {band}?',
               good, wrong, f'{good}: {why} (sliding filament theory).', r)


